create table pw_member_level (id bigint generated by default as identity primary key,level_code varchar(32) not null unique,level_name varchar(64) not null,level_no integer not null unique,min_recharge_amount decimal(14,2) not null default 0,discount_rate decimal(6,4) not null default 1,benefit_description varchar(1000),enabled boolean not null default true,sort_no integer not null default 0,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_user_member (id bigint generated by default as identity primary key,user_id bigint not null unique,level_id bigint not null,growth_value bigint not null default 0,total_recharge_amount decimal(14,2) not null default 0,started_at timestamp not null default current_timestamp,expired_at timestamp,enabled boolean not null default true,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_recharge_plan (id bigint generated by default as identity primary key,plan_code varchar(40) not null unique,plan_name varchar(80) not null,recharge_amount decimal(14,2) not null,bonus_amount decimal(14,2) not null default 0,member_days integer,sort_no integer not null default 0,enabled boolean not null default true,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_wallet_account (id bigint generated by default as identity primary key,owner_type varchar(16) not null,owner_id bigint not null,cash_balance decimal(14,2) not null default 0,bonus_balance decimal(14,2) not null default 0,frozen_balance decimal(14,2) not null default 0,version bigint not null default 0,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp,unique(owner_type,owner_id));
create table pw_recharge_order (id bigint generated by default as identity primary key,recharge_no varchar(40) not null unique,request_no varchar(64) not null,user_id bigint not null,plan_id bigint not null,recharge_amount decimal(14,2) not null,bonus_amount decimal(14,2) not null,recharge_status varchar(20) not null,paid_at timestamp,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp,unique(user_id,request_no));
create table pw_wallet_transaction (id bigint generated by default as identity primary key,transaction_no varchar(48) not null unique,account_id bigint not null,owner_type varchar(16) not null,owner_id bigint not null,balance_type varchar(16) not null,direction varchar(8) not null,business_type varchar(32) not null,business_no varchar(48) not null,amount decimal(14,2) not null,balance_before decimal(14,2) not null,balance_after decimal(14,2) not null,remark varchar(500),created_at timestamp not null default current_timestamp);
create index ix_pw_wallet_tx_owner on pw_wallet_transaction(owner_type,owner_id,id);
create index ix_pw_wallet_tx_business on pw_wallet_transaction(business_type,business_no);


