insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','CustomerWallet','wallet','/customer/wallet','我的钱包','ri:wallet-3-line',2 from sys_menu where name='CustomerPortal' and not exists(select 1 from sys_menu where name='CustomerWallet');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat('CustomerWallet',a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'View' suffix,'查看钱包' title,'customer:wallet:view' mark,1 sort_no union all select 'Recharge' suffix,'模拟充值' title,'customer:wallet:recharge' mark,2 sort_no union all select 'Transaction' suffix,'查看资金流水' title,'customer:wallet:transaction:list' mark,3 sort_no) a on 1=1 where p.name='CustomerWallet' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','RechargePlanManage','recharge-plan','/business/recharge-plan','充值套餐','ri:coupon-3-line',11 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='RechargePlanManage');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat('RechargePlan',a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'List' suffix,'查询充值套餐' title,'business:recharge-plan:list' mark,1 sort_no union all select 'Create' suffix,'新增充值套餐' title,'business:recharge-plan:create' mark,2 sort_no union all select 'Update' suffix,'编辑充值套餐' title,'business:recharge-plan:update' mark,3 sort_no union all select 'Status' suffix,'启停充值套餐' title,'business:recharge-plan:status' mark,4 sort_no) a on 1=1 where p.name='RechargePlanManage' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='customer' and (m.name='CustomerWallet' or m.auth_mark like 'customer:wallet:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and (m.name in('CustomerWallet','RechargePlanManage') or m.auth_mark like 'customer:wallet:%' or m.auth_mark like 'business:recharge-plan:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
